cd /workspace && python -c "
import numpy as np, scipy.sparse as sp
for cid in ['842bbbfcbaa65cf8c192','ca507d4594ca727cc307','d8e78b2115453c1ce7d6','c001ae8fbb3f52c2c996']:
    A=sp.load_npz(f'/input/cases/{cid}/A.npz').tocsr()
    n=int(round(A.shape[0]**0.5))
    d=A.diagonal()
    print('==',cid,'n',n)
    bad=0; tot=0; ex=[]
    for i in range(A.shape[0]):
        s,e=A.indptr[i],A.indptr[i+1]
        for j,v in zip(A.indices[s:e],A.data[s:e]):
            if j==i: continue
            tot+=1
            if abs(v + np.sqrt(d[i]*d[j])/4)>1e-9*abs(d[i]):
                bad+=1
                if len(ex)<8: ex.append((i,j,v,-np.sqrt(d[i]*d[j])/4, d[i],d[j]))
    print(' bad',bad,'/',tot)
    for e in ex: print('  ',e)
"

